def validate_frame_number(frame_number):
    assert isinstance(frame_number, int) and frame_number >= 0, "Frame number must be a non-negative integer"

# Example usage
try:
    validate_frame_number(132)  # Valid frame number
    validate_frame_number(-1)   # Invalid frame number, will raise an AssertionError
except AssertionError as e:
    print(e)
